return items.map(item => {
  const data = item.json;

  const title = data.title || '';
  const url = data.link || '';
  const publishedAt = data.pubDate || '';

  // Prefer RSS GUID as the stable advisory identifier.
  // Fall back to the URL when GUID is unavailable.
  const advisoryId =
    data.guid ||
    url ||
    title;

  return {
    json: {
      source: 'CISA',
      event_type: 'security_advisory',

      advisory_id: advisoryId,

      title,
      url,

      published_at: publishedAt,

      summary:
        data.contentSnippet ||
        data.content ||
        data.summary ||
        '',

      ingested_at: new Date().toISOString()
    }
  };
});

return items.map(item => {
  const v = item.json;
  const cve = v.cve || {};

  const descriptions = Array.isArray(cve.descriptions)
    ? cve.descriptions
    : [];

  const englishDescription =
    descriptions.find(d => d.lang === 'en')?.value || '';

  const metrics = cve.metrics || {};

  const cvss =
    metrics.cvssMetricV40?.[0]?.cvssData ||
    metrics.cvssMetricV31?.[0]?.cvssData ||
    metrics.cvssMetricV30?.[0]?.cvssData ||
    metrics.cvssMetricV2?.[0]?.cvssData ||
    null;

  return {
    json: {
      source: 'NVD',
      event_type: 'vulnerability',

      vulnerability_id: cve.id || '',

      title: cve.id || '',

      url: cve.id
        ? `https://nvd.nist.gov/vuln/detail/${cve.id}`
        : '',

      published_at: cve.published || '',
      last_modified_at: cve.lastModified || '',

      summary: englishDescription,

      cvss: cvss?.baseScore ?? null,
      severity: cvss?.baseSeverity || null,

      vector: cvss?.vectorString || '',

      references: Array.isArray(cve.references)
        ? cve.references
            .map(ref => ref.url)
            .filter(Boolean)
        : [],

      ingested_at: new Date().toISOString()
    }
  };
});

return items.map(item => {
  const data = item.json;

  const identity =
    data.vulnerability_id
      ? `CVE:${data.vulnerability_id}`
      : `URL:${data.url}`;

  return {
    json: {
      ...data,
      event_id: identity
    }
  };
});

return items.map(item => {
  const data = item.json;

  const cvss = Number(data.cvss) || 0;

  let severityScore = 0;

  if (cvss >= 9) {
    severityScore = 40;
  } else if (cvss >= 7) {
    severityScore = 30;
  } else if (cvss >= 4) {
    severityScore = 20;
  } else if (cvss > 0) {
    severityScore = 10;
  }

  const exploitabilityScore =
    data.vector?.includes('/AV:N') ? 25 : 10;

  const interactionScore =
    data.vector?.includes('/UI:N') ? 15 : 5;

  const impactScore =
    cvss >= 9 ? 20 :
    cvss >= 7 ? 15 :
    cvss >= 4 ? 10 : 5;

  const riskScore =
    severityScore +
    exploitabilityScore +
    interactionScore +
    impactScore;

  let priority = 'LOW';

  if (riskScore >= 80) {
    priority = 'CRITICAL';
  } else if (riskScore >= 60) {
    priority = 'HIGH';
  } else if (riskScore >= 40) {
    priority = 'MEDIUM';
  }

  return {
    json: {
      ...data,

      risk: {
        score: riskScore,
        priority,

        factors: {
          severity: severityScore,
          exploitability: exploitabilityScore,
          interaction: interactionScore,
          impact: impactScore
        }
      }
    }
  };
});

// ForgeX4 Security Intelligence Ranking Engine
// Deterministic editorial ranking of AI-analyzed vulnerabilities

const analyzed = [];

for (const item of $input.all()) {
  try {
    let raw = item.json.text;

    // Remove Markdown code fences if Gemini added them
    raw = raw
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/i, '')
      .replace(/\s*```$/i, '')
      .trim();

    const analysis = JSON.parse(raw);

    analyzed.push({
      ...analysis
    });

  } catch (error) {
    // Ignore malformed AI outputs
    continue;
  }
}

if (analyzed.length === 0) {
  return [];
}


// ─────────────────────────────────────────────
// Deterministic Ranking
// ─────────────────────────────────────────────

function cvssScore(cvss) {
  const value = Number(cvss) || 0;
  return Math.min(value * 10, 100);
}

function exploitationScore(text = '') {
  const value = text.toLowerCase();

  if (
    value.includes('confirmed exploitation') ||
    value.includes('actively exploited') ||
    value.includes('exploited in the wild')
  ) {
    return 100;
  }

  if (
    value.includes('remote') ||
    value.includes('arbitrary command') ||
    value.includes('root privileges') ||
    value.includes('privilege escalation')
  ) {
    return 75;
  }

  return 40;
}

function contentScore(analysis) {
  let score = 0;

  const text = (
    (analysis.technical_analysis || '') +
    ' ' +
    (analysis.exploitation_assessment || '') +
    ' ' +
    (analysis.content_angle || '')
  ).toLowerCase();

  const strongSignals = [
    'root',
    'remote code execution',
    'arbitrary command',
    'privilege escalation',
    'buffer overflow',
    'authentication bypass',
    'memory corruption',
    'command execution',
    'zero-day',
    'security architecture'
  ];

  for (const signal of strongSignals) {
    if (text.includes(signal)) {
      score += 10;
    }
  }

  return Math.min(score, 100);
}

function linkedinScore(value) {
  switch ((value || '').toUpperCase()) {
    case 'HIGH':
      return 100;

    case 'MEDIUM':
      return 60;

    default:
      return 25;
  }
}


// ─────────────────────────────────────────────
// Calculate final deterministic score
// ─────────────────────────────────────────────

const ranked = analyzed.map(analysis => {

  const cvss = cvssScore(analysis.cvss);

  const exploitation = exploitationScore(
    analysis.exploitation_assessment
  );

  const content = contentScore(analysis);

  const linkedin = linkedinScore(
    analysis.linkedin_worthiness
  );

  const finalScore =
    (cvss * 0.35) +
    (exploitation * 0.25) +
    (content * 0.25) +
    (linkedin * 0.15);

  return {
    ...analysis,

    ranking: {
      score: Number(finalScore.toFixed(2)),
      factors: {
        cvss,
        exploitation,
        content_significance: content,
        linkedin_worthiness: linkedin
      }
    }
  };
});


// Highest score first

ranked.sort(
  (a, b) =>
    b.ranking.score -
    a.ranking.score
);


// ─────────────────────────────────────────────
// Keep ranked results
// ─────────────────────────────────────────────

return ranked.map((item, index) => ({
  json: {
    rank: index + 1,
    ...item
  }
}));

const MAX_POSTS = 5;

return items
  .filter(item => Number(item.json.rank) <= MAX_POSTS)
  .sort((a, b) => Number(a.json.rank) - Number(b.json.rank));

// ForgeX4 — LinkedIn Content Quality Gate v2.1
//
// Pipeline:
//
// AI Output
//      ↓
// Normalization
//      ↓
// Metrics
//      ↓
// Hard-Fail Rules
//      ↓
// Weighted Scoring Engine
//      ↓
// Soft Warnings
//      ↓
// PASS / REVIEW / REJECT
//
// Input:
//   { output: {...} }
// OR
//   { linkedin_post, hook, key_takeaway, hashtags }
//
// Important:
// CVE is OPTIONAL.
// CVE only provides a scoring bonus.
//
// ============================================================
// CONFIGURATION
// ============================================================

const CONFIG = {

  // ----------------------------------------------------------
  // Content
  // ----------------------------------------------------------

  minPostLength: 600,
  recommendedPostLength: 750,
  maxPostLength: 1500,

  minWordCount: 90,
  recommendedWordCount: 110,

  // ----------------------------------------------------------
  // Hashtags
  // ----------------------------------------------------------

  minHashtags: 3,
  maxHashtags: 5,

  // ----------------------------------------------------------
  // Security vocabulary
  // ----------------------------------------------------------

  minSecurityTerms: 5,

  // ----------------------------------------------------------
  // Core fields
  // ----------------------------------------------------------

  minHookLength: 20,
  minTakeawayLength: 30,

  // ----------------------------------------------------------
  // Generic AI writing
  // ----------------------------------------------------------

  maxGenericPhrasesBeforePenalty: 0,

  // ----------------------------------------------------------
  // Decision thresholds
  // ----------------------------------------------------------

  passScore: 85,
  reviewScore: 70,

  // ----------------------------------------------------------
  // Weighted scoring
  //
  // Total = 100
  // ----------------------------------------------------------

  weights: {

    structure: 20,

    contentLength: 15,

    securityDepth: 20,

    technicalSpecificity: 15,

    engagement: 10,

    readability: 10,

    originality: 5,

    cveBonus: 5
  }
};


// ============================================================
// HELPERS
// ============================================================

function normalizeString(value) {

  if (typeof value !== 'string') {
    return '';
  }

  return value
    .replace(/\r\n/g, '\n')
    .trim();
}


// ------------------------------------------------------------
// Hashtags
// ------------------------------------------------------------

function normalizeHashtags(value) {

  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .map(tag => String(tag).trim())
    .filter(Boolean)
    .map(tag =>
      tag.startsWith('#')
        ? tag
        : `#${tag}`
    );
}


// ------------------------------------------------------------
// Word count
// ------------------------------------------------------------

function countWords(text) {

  if (!text) {
    return 0;
  }

  return text
    .trim()
    .split(/\s+/)
    .filter(Boolean)
    .length;
}


// ------------------------------------------------------------
// CVE extraction
// ------------------------------------------------------------

function extractCVEs(text) {

  if (!text) {
    return [];
  }

  const matches =
    text.match(/\bCVE-\d{4}-\d{4,7}\b/gi) || [];

  return [
    ...new Set(
      matches.map(
        cve => cve.toUpperCase()
      )
    )
  ];
}


// ============================================================
// SECURITY TERMINOLOGY
// ============================================================

function countSecurityTerms(text) {

  if (!text) {
    return 0;
  }

  const securityTerms = [

    // Vulnerability
    'vulnerability',
    'vulnerabilities',
    'CVE',
    'CVSS',
    'exploit',
    'exploitation',

    // Threat actors
    'attacker',
    'attack',
    'remote attacker',
    'local attacker',

    // Identity / authorization
    'authentication',
    'authorization',
    'access control',
    'authentication boundary',
    'authorization boundary',

    // Privilege
    'root',
    'root access',
    'root privileges',
    'privilege',
    'privilege escalation',
    'least privilege',
    'privilege separation',

    // Network
    'remote',
    'local',
    'network',
    'network exposure',
    'attack vector',
    'attack complexity',

    // Execution
    'command execution',
    'arbitrary command',
    'arbitrary code execution',
    'command injection',

    // System
    'kernel',
    'daemon',
    'setuid',
    'debug',
    'system compromise',

    // Defensive
    'hardening',
    'mitigation',
    'secure configuration',
    'misconfiguration',

    // Software weaknesses
    'input validation',
    'memory corruption',
    'buffer overflow',

    // CIA
    'integrity',
    'confidentiality',
    'availability',

    // Architecture
    'trust boundary'
  ];

  const lower =
    text.toLowerCase();

  return securityTerms.filter(term =>
    lower.includes(
      term.toLowerCase()
    )
  ).length;
}


// ============================================================
// EXPLOITATION / SAFETY DETECTION
// ============================================================

function detectExploitationClaim(text) {

  if (!text) {
    return false;
  }

  const lower =
    text.toLowerCase();

  const dangerousPatterns = [

    'actively exploited',
    'actively being exploited',
    'currently exploited',
    'currently being exploited',

    'exploited in the wild',
    'exploitation in the wild',

    'under active exploitation',

    'attackers are exploiting',
    'attackers are actively exploiting',

    'has been actively exploited',
    'was actively exploited',

    'currently under attack',

    'being exploited right now'
  ];

  return dangerousPatterns.some(
    pattern =>
      lower.includes(pattern)
  );
}


// ============================================================
// GENERIC AI WRITING DETECTION
// ============================================================

function detectGenericPhrases(text) {

  if (!text) {
    return [];
  }

  const genericPatterns = [

    'this vulnerability highlights the importance of',

    'this vulnerability underscores the importance of',

    'this highlights the importance of',

    'this underscores the importance of',

    'serves as a stark reminder',

    'serves as a reminder of the importance',

    'it is important to note that',

    'in today’s rapidly evolving',

    "in today's rapidly evolving",

    'in the ever-evolving cybersecurity landscape',

    'as we navigate the evolving',

    'cybersecurity is more important than ever',

    'in the modern cybersecurity landscape',

    'this case study demonstrates the importance',

    'this case study highlights the importance',

    'in an increasingly connected world',

    'in today’s digital landscape',

    "in today's digital landscape"
  ];

  const lower =
    text.toLowerCase();

  return genericPatterns.filter(
    pattern =>
      lower.includes(
        pattern.toLowerCase()
      )
  );
}


// ============================================================
// ENGAGEMENT
// ============================================================

function hasDiscussionQuestion(text) {

  if (!text) {
    return false;
  }

  return (
    text.includes('?') ||
    text.includes('؟')
  );
}


function hasHook(hook) {

  return (
    normalizeString(hook).length >=
    CONFIG.minHookLength
  );
}


function hasKeyTakeaway(keyTakeaway) {

  return (
    normalizeString(keyTakeaway).length >=
    CONFIG.minTakeawayLength
  );
}


// ============================================================
// HASHTAG VALIDATION
// ============================================================

function validateHashtags(hashtags) {

  if (!Array.isArray(hashtags)) {
    return false;
  }

  if (
    hashtags.length <
      CONFIG.minHashtags ||
    hashtags.length >
      CONFIG.maxHashtags
  ) {
    return false;
  }

  return hashtags.every(tag => {

    if (typeof tag !== 'string') {
      return false;
    }

    const trimmed =
      tag.trim();

    return /^#[A-Za-z0-9_]+$/
      .test(trimmed);
  });
}


// ============================================================
// TECHNICAL SPECIFICITY
// ============================================================

function calculateTechnicalSpecificity(
  text,
  metrics
) {

  if (!text) {
    return 0;
  }

  let score = 0;


  // ----------------------------------------------------------
  // CVE identifier
  // ----------------------------------------------------------

  if (metrics.cveCount > 0) {
    score += 25;
  }


  // ----------------------------------------------------------
  // CVSS
  // ----------------------------------------------------------

  if (/\bCVSS\b/i.test(text)) {
    score += 10;
  }


  // ----------------------------------------------------------
  // Explicit technical command
  //
  // Example:
  // CWD ~root
  // chmod
  // exec()
  // setuid()
  // etc.
  // ----------------------------------------------------------

  if (
    /\b[A-Za-z_][A-Za-z0-9_]*\s*~\s*[A-Za-z0-9_]+/
      .test(text)
  ) {
    score += 15;
  }


  // ----------------------------------------------------------
  // Unix paths
  // ----------------------------------------------------------

  if (
    /\/[A-Za-z0-9._~/-]+/
      .test(text)
  ) {
    score += 10;
  }


  // ----------------------------------------------------------
  // Version numbers
  // ----------------------------------------------------------

  if (
    /\b(?:version\s*)?\d+\.\d+(?:\.\d+)?(?:\.\d+)?\b/i
      .test(text)
  ) {
    score += 10;
  }


  // ----------------------------------------------------------
  // Numeric technical values
  //
  // CVSS score, version, port, year, etc.
  // ----------------------------------------------------------

  if (
    /\b\d+(?:\.\d+)?\b/
      .test(text)
  ) {
    score += 5;
  }


  // ----------------------------------------------------------
  // Technical security vocabulary
  // ----------------------------------------------------------

  if (
    metrics.securityTermCount >= 10
  ) {

    score += 25;

  } else if (
    metrics.securityTermCount >= 7
  ) {

    score += 20;

  } else if (
    metrics.securityTermCount >= 5
  ) {

    score += 12;
  }


  return Math.min(
    100,
    score
  );
}


// ============================================================
// READABILITY
// ============================================================

function calculateReadability(
  text,
  wordCount
) {

  if (
    !text ||
    wordCount === 0
  ) {
    return 0;
  }

  let score = 100;

  const sentences =
    text
      .split(/[.!?؟]+/)
      .filter(Boolean);

  if (
    sentences.length === 0
  ) {
    return 50;
  }

  const averageWordsPerSentence =
    wordCount /
    sentences.length;


  // Very long sentences

  if (
    averageWordsPerSentence > 35
  ) {

    score -= 25;

  } else if (
    averageWordsPerSentence > 28
  ) {

    score -= 15;

  } else if (
    averageWordsPerSentence > 22
  ) {

    score -= 8;
  }


  // Fragmented writing

  if (
    averageWordsPerSentence < 7
  ) {

    score -= 15;
  }


  // Extremely dense paragraph

  const paragraphs =
    text
      .split(/\n\s*\n/)
      .filter(Boolean);

  if (
    paragraphs.length === 1 &&
    wordCount > 130
  ) {

    score -= 5;
  }


  return Math.max(
    0,
    Math.min(100, score)
  );
}


// ============================================================
// CONTENT LENGTH SCORE
// ============================================================

function calculateLengthScore(
  postLength,
  wordCount
) {

  let score = 100;


  // Serious shortness

  if (
    postLength <
    CONFIG.minPostLength
  ) {

    score -= 50;
  }


  // Word count

  if (
    wordCount <
    CONFIG.minWordCount
  ) {

    score -= 30;
  }


  // Excessive length

  if (
    postLength >
    CONFIG.maxPostLength
  ) {

    score -= 15;
  }


  // Slightly below recommended
  // is NOT a serious problem.

  if (
    postLength >=
      CONFIG.minPostLength &&
    postLength <
      CONFIG.recommendedPostLength
  ) {

    score -= 5;
  }


  if (
    wordCount >=
    CONFIG.recommendedWordCount &&
    postLength >=
    CONFIG.recommendedPostLength
  ) {

    score += 0;
  }


  return Math.max(
    0,
    Math.min(100, score)
  );
}


// ============================================================
// SECURITY DEPTH SCORE
// ============================================================

function calculateSecurityDepth(
  metrics
) {

  const count =
    metrics.securityTermCount;


  if (count >= 12) {
    return 100;
  }

  if (count >= 9) {
    return 90;
  }

  if (count >= 7) {
    return 80;
  }

  if (count >= 5) {
    return 70;
  }

  if (count >= 3) {
    return 50;
  }

  return 25;
}


// ============================================================
// STRUCTURE SCORE
// ============================================================

function calculateStructureScore(
  checks
) {

  let score = 0;

  if (checks.has_post) {
    score += 40;
  }

  if (checks.has_hook) {
    score += 20;
  }

  if (checks.has_key_takeaway) {
    score += 20;
  }

  if (checks.hashtags_valid) {
    score += 20;
  }

  return Math.min(
    100,
    score
  );
}


// ============================================================
// ENGAGEMENT SCORE
// ============================================================

function calculateEngagementScore(
  checks
) {

  let score = 0;


  // Question is valuable,
  // but NOT mandatory.

  if (
    checks.has_discussion_question
  ) {

    score += 70;
  }


  // Hook contributes to engagement.

  if (
    checks.has_hook
  ) {

    score += 30;
  }


  return Math.min(
    100,
    score
  );
}


// ============================================================
// ORIGINALITY SCORE
// ============================================================

function calculateOriginalityScore(
  genericPhraseCount
) {

  if (
    genericPhraseCount === 0
  ) {
    return 100;
  }

  if (
    genericPhraseCount === 1
  ) {
    return 85;
  }

  if (
    genericPhraseCount === 2
  ) {
    return 65;
  }

  if (
    genericPhraseCount === 3
  ) {
    return 45;
  }

  return 25;
}


// ============================================================
// MAIN PROCESS
// ============================================================

return items.map((item) => {

  const raw =
    item.json || {};


  // ----------------------------------------------------------
  // Resolve AI output
  // ----------------------------------------------------------

  const data =
    raw.output &&
    typeof raw.output === 'object' &&
    !Array.isArray(raw.output)

      ? raw.output

      : raw;


  // ----------------------------------------------------------
  // Normalize
  // ----------------------------------------------------------

  const linkedin_post =
    normalizeString(
      data.linkedin_post
    );

  const hook =
    normalizeString(
      data.hook
    );

  const key_takeaway =
    normalizeString(
      data.key_takeaway
    );

  const hashtags =
    normalizeHashtags(
      data.hashtags
    );


  // ----------------------------------------------------------
  // Combined text
  // ----------------------------------------------------------

  const combinedText =
    `${linkedin_post} ${hook} ${key_takeaway}`;


  // ----------------------------------------------------------
  // Metrics
  // ----------------------------------------------------------

  const postLength =
    linkedin_post.length;

  const wordCount =
    countWords(
      linkedin_post
    );

  const cves =
    extractCVEs(
      combinedText
    );

  const cveCount =
    cves.length;

  const hashtagCount =
    hashtags.length;

  const securityTermCount =
    countSecurityTerms(
      combinedText
    );


  // ----------------------------------------------------------
  // Checks
  // ----------------------------------------------------------

  const exploitationClaimDetected =
    detectExploitationClaim(
      combinedText
    );

  const detectedGenericPhrases =
    detectGenericPhrases(
      linkedin_post
    );

  const genericPhraseCount =
    detectedGenericPhrases.length;

  const discussionQuestion =
    hasDiscussionQuestion(
      linkedin_post
    );

  const hookValid =
    hasHook(
      hook
    );

  const keyTakeawayValid =
    hasKeyTakeaway(
      key_takeaway
    );

  const hashtagsValid =
    validateHashtags(
      hashtags
    );


  // ----------------------------------------------------------
  // Structural checks
  // ----------------------------------------------------------

  const checks = {

    has_post:
      Boolean(linkedin_post),

    has_hook:
      hookValid,

    has_key_takeaway:
      keyTakeawayValid,

    has_discussion_question:
      discussionQuestion,

    hashtags_valid:
      hashtagsValid,

    exploitation_claim_detected:
      exploitationClaimDetected,

    generic_phrase_count:
      genericPhraseCount,

    detected_generic_phrases:
      detectedGenericPhrases
  };


  // ==========================================================
  // HARD FAILURES
  // ==========================================================

  const hardFailures = [];


  // Empty post

  if (!linkedin_post) {

    hardFailures.push(
      'LinkedIn post is empty'
    );
  }


  // Missing hook

  if (!hook) {

    hardFailures.push(
      'Hook is missing'
    );
  }


  // Missing takeaway

  if (!key_takeaway) {

    hardFailures.push(
      'Key takeaway is missing'
    );
  }


  // Hashtags must be an array

  if (
    !Array.isArray(
      data.hashtags
    )
  ) {

    hardFailures.push(
      'Hashtags field must be an array'
    );
  }


  // Serious short post

  if (
    linkedin_post &&
    postLength <
    CONFIG.minPostLength
  ) {

    hardFailures.push(
      `Post is too short (${postLength} characters; minimum ${CONFIG.minPostLength})`
    );
  }


  // Too few hashtags

  if (
    hashtagCount <
    CONFIG.minHashtags
  ) {

    hardFailures.push(
      `Fewer than ${CONFIG.minHashtags} hashtags`
    );
  }


  // Too many hashtags

  if (
    hashtagCount >
    CONFIG.maxHashtags
  ) {

    hardFailures.push(
      `More than ${CONFIG.maxHashtags} hashtags`
    );
  }


  // Invalid hashtags

  if (
    Array.isArray(
      data.hashtags
    ) &&
    !hashtagsValid
  ) {

    hardFailures.push(
      'One or more hashtags are invalid'
    );
  }


  // Unsupported active exploitation claim

  if (
    exploitationClaimDetected
  ) {

    hardFailures.push(
      'Potential unsupported active-exploitation claim detected'
    );
  }


  // ==========================================================
  // SOFT WARNINGS
  // ==========================================================

  const warnings = [];


  // ----------------------------------------------------------
  // CVE
  //
  // IMPORTANT:
  // CVE is OPTIONAL.
  // ----------------------------------------------------------

  if (
    cveCount === 0
  ) {

    warnings.push(
      'No CVE identifier detected; CVE is optional for historical or non-CVE security content'
    );
  }


  // ----------------------------------------------------------
  // Word count
  // ----------------------------------------------------------

  if (
    wordCount <
    CONFIG.minWordCount
  ) {

    warnings.push(
      `Post has low word count (${wordCount}; recommended minimum ${CONFIG.minWordCount})`
    );
  }


  // ----------------------------------------------------------
  // Security terminology
  // ----------------------------------------------------------

  if (
    securityTermCount <
    CONFIG.minSecurityTerms
  ) {

    warnings.push(
      `Limited security-specific terminology detected (${securityTermCount})`
    );
  }


  // ----------------------------------------------------------
  // Discussion question
  //
  // WARNING ONLY
  // ----------------------------------------------------------

  if (
    !discussionQuestion
  ) {

    warnings.push(
      'Post does not contain a discussion question'
    );
  }


  // ----------------------------------------------------------
  // Hook
  // ----------------------------------------------------------

  if (
    !hookValid
  ) {

    warnings.push(
      'Hook may be too short'
    );
  }


  // ----------------------------------------------------------
  // Takeaway
  // ----------------------------------------------------------

  if (
    !keyTakeawayValid
  ) {

    warnings.push(
      'Key takeaway may be too short'
    );
  }


  // ----------------------------------------------------------
  // Generic AI writing
  // ----------------------------------------------------------

  if (
    genericPhraseCount >
    CONFIG.maxGenericPhrasesBeforePenalty
  ) {

    warnings.push(
      `${genericPhraseCount} generic AI-style phrase(s) detected`
    );
  }


  // ----------------------------------------------------------
  // Excessive length
  // ----------------------------------------------------------

  if (
    postLength >
    CONFIG.maxPostLength
  ) {

    warnings.push(
      `Post is longer than recommended maximum (${postLength} characters)`
    );
  }


  // ==========================================================
  // SCORING ENGINE
  // ==========================================================

  const structureScore =
    calculateStructureScore(
      checks
    );


  const lengthScore =
    calculateLengthScore(
      postLength,
      wordCount
    );


  const securityDepthScore =
    calculateSecurityDepth({
      securityTermCount
    });


  const technicalSpecificityScore =
    calculateTechnicalSpecificity(
      combinedText,
      {
        cveCount,
        securityTermCount
      }
    );


  const engagementScore =
    calculateEngagementScore(
      checks
    );


  const readabilityScore =
    calculateReadability(
      linkedin_post,
      wordCount
    );


  const originalityScore =
    calculateOriginalityScore(
      genericPhraseCount
    );


  // ----------------------------------------------------------
  // CVE BONUS
  //
  // CVE is never required.
  // ----------------------------------------------------------

  const cveBonus =
    cveCount > 0
      ? 100
      : 0;


  // ==========================================================
  // WEIGHTED SCORE
  // ==========================================================

  const weightedScores = {

    structure:
      structureScore *
      (CONFIG.weights.structure / 100),

    content_length:
      lengthScore *
      (CONFIG.weights.contentLength / 100),

    security_depth:
      securityDepthScore *
      (CONFIG.weights.securityDepth / 100),

    technical_specificity:
      technicalSpecificityScore *
      (CONFIG.weights.technicalSpecificity / 100),

    engagement:
      engagementScore *
      (CONFIG.weights.engagement / 100),

    readability:
      readabilityScore *
      (CONFIG.weights.readability / 100),

    originality:
      originalityScore *
      (CONFIG.weights.originality / 100),

    cve_bonus:
      cveBonus *
      (CONFIG.weights.cveBonus / 100)
  };


  // ----------------------------------------------------------
  // Base score
  // ----------------------------------------------------------

  let score =
    Object.values(
      weightedScores
    ).reduce(
      (sum, value) =>
        sum + value,
      0
    );


  // ==========================================================
  // PENALTIES
  // ==========================================================

  // Generic AI-style writing

  score -= Math.min(
    genericPhraseCount * 3,
    9
  );


  // Unsupported active exploitation claim

  if (
    exploitationClaimDetected
  ) {

    score -= 30;
  }


  // Clamp and round

  score =
    Math.round(
      Math.max(
        0,
        Math.min(
          100,
          score
        )
      )
    );


  // ==========================================================
  // FINAL DECISION
  // ==========================================================

  let status;


  if (
    hardFailures.length > 0
  ) {

    status = 'REJECT';

  } else if (
    score < CONFIG.reviewScore
  ) {

    status = 'REJECT';

  } else if (
    score < CONFIG.passScore
  ) {

    status = 'REVIEW';

  } else {

    status = 'PASS';
  }


  // ==========================================================
  // SCORE BREAKDOWN
  // ==========================================================

  const scoreBreakdown = {

    structure:
      Math.round(
        weightedScores.structure
      ),

    content_length:
      Math.round(
        weightedScores.content_length
      ),

    security_depth:
      Math.round(
        weightedScores.security_depth
      ),

    technical_specificity:
      Math.round(
        weightedScores.technical_specificity
      ),

    engagement:
      Math.round(
        weightedScores.engagement
      ),

    readability:
      Math.round(
        weightedScores.readability
      ),

    originality:
      Math.round(
        weightedScores.originality
      ),

    cve_bonus:
      Math.round(
        weightedScores.cve_bonus
      )
  };


  // ==========================================================
  // FINAL OUTPUT
  // ==========================================================

  return {

    json: {

      linkedin_post,

      hook,

      key_takeaway,

      hashtags,


      quality_gate: {

        status,

        quality_score:
          score,


        score_breakdown:
          scoreBreakdown,


        thresholds: {

          pass:
            CONFIG.passScore,

          review:
            CONFIG.reviewScore,

          reject:
            `< ${CONFIG.reviewScore}`
        },


        metrics: {

          post_length:
            postLength,

          word_count:
            wordCount,

          hashtag_count:
            hashtagCount,

          cve_count:
            cveCount,

          cves,

          security_term_count:
            securityTermCount
        },


        checks,


        hard_failures:
          hardFailures,


        issues:
          hardFailures,


        warnings
      }
    }
  };
});

// ForgeX4 Temporal State Management (Perimeter Filter)
// Enforces O(1) lookups to prevent duplicate vulnerability reporting

const staticData = $getWorkflowStaticData('global');
staticData.processedEvents = staticData.processedEvents || [];

// ⚠️ DEVELOPER OVERRIDE: 
// Uncomment the line below while testing to wipe the memory clean on every run.
// staticData.processedEvents = []; 

const MAX_HISTORY = 1000; 
const uniqueItems = [];

for (const item of $input.all()) {
  // We grab the ID directly from the source now
  const eventId = item.json.event_id;

  if (!eventId) continue; // Drop malformed state

  if (!staticData.processedEvents.includes(eventId)) {
    // Event is novel; append to ledger and pass through
    staticData.processedEvents.push(eventId);
    uniqueItems.push(item);
  }
}

// Prune historical state to prevent memory overflow
if (staticData.processedEvents.length > MAX_HISTORY) {
  staticData.processedEvents = staticData.processedEvents.slice(-MAX_HISTORY);
}

return uniqueItems;

